
  function download(name,blob){const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(a.href),1500);}
  function backupJSON(){download(`K2-backup-${todayISO()}.json`,new Blob([JSON.stringify({app:'K2-preview',version:1,exportedAt:new Date().toISOString(),state},null,2)],{type:'application/json;charset=utf-8'}));notify('نسخهٔ پشتیبان JSON دانلود شد');}
  async function saveHTML(){const html='<!doctype html>\n'+document.documentElement.outerHTML.replace(/(<script id="embeddedState" type="application\/json">)[\s\S]*?(<\/script>)/,(_,a,b)=>a+JSON.stringify(state).replace(/</g,'\\u003c')+b);const blob=new Blob([html],{type:'text/html;charset=utf-8'});if(window.showSaveFilePicker){try{const h=await showSaveFilePicker({suggestedName:'K2-preview-with-data.html',types:[{description:'Standalone HTML',accept:{'text/html':['.html']}}]});const w=await h.createWritable();await w.write(blob);await w.close();notify('نسخهٔ HTML داده‌دار ذخیره شد');return;}catch(e){if(e.name==='AbortError')return;}}download(`K2-preview-with-data-${todayISO()}.html`,blob);notify('HTML خودبسنده دانلود شد؛ برای حمل داده همین فایل را نگه دارید');}
  async function restoreFile(file){try{const text=await file.text();let data;if(file.name.toLowerCase().endsWith('.html')){const doc=new DOMParser().parseFromString(text,'text/html');data=JSON.parse(doc.querySelector('#embeddedState')?.textContent||'null');}else{const raw=JSON.parse(text);data=raw.state||raw;}if(!data||typeof data!=='object'||!Array.isArray(data.activities)||!Array.isArray(data.events))throw new Error('ساختار فایل با پشتیبان K2 سازگار نیست');if(!confirm('اطلاعات فعلی با داده‌های فایل جایگزین شود؟ این عمل قابل بازگشت نیست مگر از پشتیبان فعلی استفاده کنید.'))return;state={...fresh(),...data,settings:{...fresh().settings,...data.settings},onboarding:{...fresh().onboarding,...data.onboarding}};try{localStorage.setItem(STORE_KEY,JSON.stringify(state))}catch(e){console.warn('Browser storage unavailable; restored in memory',e)}currentPage='dashboard';render();notify('داده‌ها بازیابی شدند')}catch(e){alert(`بازیابی نشد: ${e.message}`);}}
  function addRemediation(){const a=state.attempts[0];if(!a){notify('ابتدا آزمون ثبت کنید');return;}const subject=state.subjects.find(s=>s.id===a.subjectId);state.activities.unshift({id:id(),title:`رفع اشکال ${a.error||'آزمون'} · ${a.name}`,type:'remediation',subjectId:subject?.id||'',subjectName:subject?.name||'',estimate:45,remaining:45,minChunk:20,maxChunk:60,splittable:true,deadline:'none',state:'planned',personalWeight:1,reason:`بر اساس نتیجهٔ آزمون ${a.name}`});saveAndRender('فعالیت اصلاحی ساخته شد');}
  function actStatus(a,op){if(op==='start'){if(a.state==='done'||a.state==='dropped'){notify('گذار از وضعیت پایانی ممکن نیست');return;}a.state='in_progress';a.reason='شروع ثبت شد';}
    else if(op==='complete'){const actual=prompt('زمان واقعی انجام (دقیقه):',String(a.remaining||a.estimate));if(actual===null)return;a.actual=num(a.actual)+num(actual);a.remaining=0;a.state='done';a.reason='تکمیل شد';if(a.backlogId)syncBacklog(a.backlogId,num(actual));}
    else if(op==='partial'){const done=prompt('چند دقیقه انجام شد؟',String(Math.min(30,a.remaining||a.estimate)));if(done===null)return;const d=Math.max(0,Math.min(num(done),num(a.remaining||a.estimate)));if(!d){notify('زمان انجام‌شده باید بیشتر از صفر باشد');return;}a.actual=num(a.actual)+d;a.remaining=Math.max(0,num(a.remaining||a.estimate)-d);a.state=a.remaining?'partial':'done';a.reason='پیشرفت ناقص ثبت شد';if(a.backlogId)syncBacklog(a.backlogId,d);}
    else if(op==='defer'||op==='drop'){const reason=prompt(op==='defer'?'دلیل تعویق را بنویسید:':'برای حذف دلیل بنویسید:');if(!reason?.trim())return;a.state=op==='defer'?'deferred':'dropped';a.reason=reason.trim();}
    else if(op==='edit'){addActivityForm(a);return;}a.updatedAt=new Date().toISOString();saveAndRender('وضعیت فعالیت ذخیره شد');}
