    if(wizard==='class'||wizard==='event'){const sid=v('subject');const subject=selectedSubjects().find(s=>s.id===sid||s.name===sid);const ev={id:id(),title:String(v('title')).trim(),kind:v('kind'),weekday:num(v('weekday')),subjectId:sid||'',subjectName:subject?.name||'',start:v('start'),end:v('end'),recorded:d.has('recorded'),note:v('note')||''};if(minOf(ev.end)<=minOf(ev.start)){notify('زمان پایان باید پس از شروع باشد');return;}const arrKey=wizard==='class'?'classes':'commitments';state.onboarding.values[arrKey]=[...(state.onboarding.values[arrKey]||[]),ev];persist('رویداد راه‌اندازی ذخیره شد');closeDialog();render();return;}
