      if(action==='close-dialog'){closeDialog();return;}
      if(action==='add-resource'){resourceForm(null);return;}
      if(action==='save-resource'){const f=$('#modalForm');if(f)submitResource(f);return;}
      if(action.startsWith('resource-edit:')){resourceForm(action.split(':').slice(1).join(':'));return;}
      if(action.startsWith('resource-delete:')){const rid=action.split(':').slice(1).join(':');const r=(state.resources||[]).find(x=>x.id===rid);if(r&&confirm(`منبع «${r.title}» حذف شود؟ این عمل قابل بازگشت نیست.`)){state.resources=(state.resources||[]).filter(x=>x.id!==rid);persist('منبع حذف شد');render();}return;}
      if(action.startsWith('resource-subject:')){resourceSubject=action.split(':').slice(1).join(':');render();return;}
      if(action.startsWith('resources:')){const [,subject,chapter,section]=action.split(':');resourceForm(null,{subject,chapter:Number(chapter),section:Number(section)});return;}
      if(action.startsWith('assess:')){const [,subject,grade,chapter,section]=action.split(':');assessStart(subject,Number(grade),Number(chapter),Number(section));return;}
      if(action==='assess-back'){assessCollect();assessDraft.step=Math.max(0,assessDraft.step-1);assessRender();return;}
      if(action==='assess-next'){assessCollect();if(assessDraft.step<ASSESS_QUESTIONS.length&&!assessDraft.answers[ASSESS_QUESTIONS[assessDraft.step].key]){notify('یک گزینه را انتخاب کن؛ اگر مطمئن نیستی «نمی‌دانم» را انتخاب کن');return;}assessDraft.step++;assessRender();return;}
